type RollupMutation struct {
	config
	op              Op
	typ             string
	id              *int64
	resolution      *rollup.Resolution
	bucket          *time.Time
	checks          *int64
	addchecks       *int64
	successes       *int64
	addsuccesses    *int64
	rt_sum_ms       *int64
	addrt_sum_ms    *int64
	rt_min_ms       *int64
	addrt_min_ms    *int64
	rt_max_ms       *int64
	addrt_max_ms    *int64
	clearedFields   map[string]struct{}
	endpoint        *int
	clearedendpoint bool
	done            bool
	oldValue        func(context.Context) (*Rollup, error)
	predicates      []predicate.Rollup
}

